// CheckpointReader is the minimal surface the dashboard needs to resolve
// /api/checkpoint/<id> on demand. It mirrors checkpoint.GitStore.ReadCommitted
// so tests can inject a fake reader without spinning up a real git repo.
type CheckpointReader interface {
	ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*checkpoint.CheckpointSummary, error)
}

// Server is the loopback dashboard. Construct via New and start with Start.
type Server struct {
	store     *graph.Store
	cpReader  CheckpointReader
	listener  net.Listener
	server    *http.Server
	token     string
	addr      string
	startedAt time.Time
	serveErr  error
}

// New builds an unstarted server bound to the given store.
//
// cpReader is optional; pass nil to keep the on-demand checkpoint endpoint
// disabled (it returns 404 with an explanatory message). Pass a real
// CheckpointReader (e.g. checkpoint.NewGitStore(repo)) to expose
// /api/checkpoint/<id> with metadata + summary on demand.
func New(store *graph.Store, cpReader CheckpointReader) (*Server, error) {
	if store == nil {
		return nil, errors.New("dashboard: nil store")
	}
	tok, err := mintToken()
	if err != nil {
		return nil, err
	}
	return &Server{store: store, cpReader: cpReader, token: tok}, nil
}

