// CheckpointDetail is the JSON shape returned by /api/checkpoint/<id>. It
// surfaces metadata + an AI summary when present but never raw transcript
// bodies — the spec is explicit that bulk index endpoints must not expose
// transcripts. Per-checkpoint prompt content is intentionally omitted from
// this v1 endpoint; surfacing it requires an additional auth check tied to
// the user's session, which is a follow-up.
type CheckpointDetail struct {
	CheckpointID     string   `json:"checkpoint_id"`
	Strategy         string   `json:"strategy,omitempty"`
	Branch           string   `json:"branch,omitempty"`
	CheckpointsCount int      `json:"checkpoints_count"`
	FilesTouched    []string `json:"files_touched"`
	SessionIDs      []string `json:"session_ids,omitempty"`
	HasSummary      bool     `json:"has_summary,omitempty"`
}

// handleCheckpointDetail looks up a committed checkpoint by id and returns
// its public metadata when a CheckpointReader is configured. When no reader
// is configured the endpoint returns 503 (service unavailable) with an
// explanatory message — keeping the route gated behind requireToken so a
// future widening can't accidentally bypass auth.
func (s *Server) handleCheckpointDetail(w http.ResponseWriter, r *http.Request) {
	if s.cpReader == nil {
		http.Error(w, "checkpoint detail unavailable: server started without a CheckpointReader", http.StatusServiceUnavailable)
		return
	}
	rawID := strings.TrimPrefix(r.URL.Path, "/api/checkpoint/")
	rawID = strings.Trim(rawID, "/")
	if rawID == "" {
		http.Error(w, "missing checkpoint id", http.StatusBadRequest)
		return
	}
	cpID, err := id.NewCheckpointID(rawID)
	if err != nil {
		http.Error(w, "invalid checkpoint id", http.StatusBadRequest)
		return
	}
	summary, err := s.cpReader.ReadCommitted(r.Context(), cpID)
	if err != nil {
		http.Error(w, "checkpoint lookup failed", http.StatusInternalServerError)
		return
	}
	if summary == nil {
		http.Error(w, "checkpoint not found", http.StatusNotFound)
		return
	}
	detail := CheckpointDetail{
		CheckpointID:     summary.CheckpointID.String(),
		Strategy:         summary.Strategy,
		Branch:           summary.Branch,
		CheckpointsCount: summary.CheckpointsCount,
		FilesTouched:     summary.FilesTouched,
	}
	for _, sess := range summary.Sessions {
		detail.SessionIDs = append(detail.SessionIDs, sess.SessionID)
	}
	writeJSON(w, detail)
}

